const { owner_id = '' } = query;
const supabaseUrl = ($env && $env.SUPABASE_URL) ? $env.SUPABASE_URL : 'https://SEU_PROJETO.supabase.co';
const serviceKey  = ($env && $env.SUPABASE_SERVICE_KEY) ? $env.SUPABASE_SERVICE_KEY : 'SUA_SERVICE_KEY';

try {
  const result = await this.helpers.httpRequest({
    method: 'GET',
    url: supabaseUrl + '/rest/v1/stock_items',
    headers: { apikey: serviceKey, Authorization: 'Bearer ' + serviceKey },
    qs: {
      owner_id: 'eq.' + owner_id,
      select: 'id,name,category,unit,current_stock,min_stock,cost_price,supplier,last_purchase_date',
      order: 'current_stock.asc'
    }
  });
  return JSON.stringify(result);
} catch (e) {
  return JSON.stringify({ error: e.message, tool: 'nivel_estoque' });
}

const { owner_id = '', item_name = '' } = query;
const supabaseUrl = ($env && $env.SUPABASE_URL) ? $env.SUPABASE_URL : 'https://SEU_PROJETO.supabase.co';
const serviceKey  = ($env && $env.SUPABASE_SERVICE_KEY) ? $env.SUPABASE_SERVICE_KEY : 'SUA_SERVICE_KEY';

try {
  const result = await this.helpers.httpRequest({
    method: 'GET',
    url: supabaseUrl + '/rest/v1/supplier_messages',
    headers: { apikey: serviceKey, Authorization: 'Bearer ' + serviceKey },
    qs: {
      owner_id: 'eq.' + owner_id,
      content: 'ilike.*' + item_name + '*',
      select: 'supplier_name,supplier_phone,item_name,price_per_unit,unit,quantity,created_at,delivery_days',
      order: 'created_at.desc',
      limit: '20'
    }
  });
  return JSON.stringify(result);
} catch (e) {
  return JSON.stringify({ error: e.message, tool: 'historico_precos_fornecedor' });
}

const {
  owner_id = '',
  item_name = '',
  quantity = 0,
  unit = 'kg',
  supplier_name = '',
  estimated_price_unit = 0,
  urgency = 'normal',
  needed_by_date = ''
} = query;

const supabaseUrl = ($env && $env.SUPABASE_URL) ? $env.SUPABASE_URL : 'https://SEU_PROJETO.supabase.co';
const serviceKey  = ($env && $env.SUPABASE_SERVICE_KEY) ? $env.SUPABASE_SERVICE_KEY : 'SUA_SERVICE_KEY';

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: supabaseUrl + '/rest/v1/purchase_list_items',
    headers: {
      apikey: serviceKey,
      Authorization: 'Bearer ' + serviceKey,
      'Content-Type': 'application/json',
      Prefer: 'return=minimal'
    },
    body: JSON.stringify({
      owner_id,
      item_name,
      quantity: Number(quantity),
      unit,
      supplier_name,
      estimated_price_unit: Number(estimated_price_unit),
      estimated_total: Number(quantity) * Number(estimated_price_unit),
      urgency,
      needed_by_date,
      status: 'pendente'
    })
  });
  return JSON.stringify({ success: true, item: item_name, quantity, urgency });
} catch (e) {
  return JSON.stringify({ error: e.message, tool: 'salvar_lista_compras' });
}

const item = items[0];
const raw = item.json.output || item.json.text || item.json;
let data;
try {
  const clean = (typeof raw === 'string') ? raw.replace(/```json\n?/gi, '').replace(/```/g, '').trim() : JSON.stringify(raw);
  data = JSON.parse(clean);
} catch (e) {
  data = { raw_output: raw };
}
return [{ json: { success: true, agente: 'COMPRAS', setor: item.json.setor, owner_id: item.json.owner_id, timestamp: new Date().toISOString(), data } }];
